import{_ as a,c as n,o as i,ag as e}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"HMI till PLC kommunikation","description":"","frontmatter":{},"headers":[],"relativePath":"06-kommunikation/hmi-till-plc.md","filePath":"06-kommunikation/hmi-till-plc.md","lastUpdated":1768470380000}'),r={name:"06-kommunikation/hmi-till-plc.md"};function s(o,t,l,g,d,p){return i(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="hmi-till-plc-kommunikation" tabindex="-1">HMI till PLC kommunikation <a class="header-anchor" href="#hmi-till-plc-kommunikation" aria-label="Permalink to &quot;HMI till PLC kommunikation&quot;">​</a></h1><p>Detta avsnitt beskriver hur HMI-panelen kommunicerar med PLC:n - från grundläggande konfiguration till optimering och felsökning.</p><h2 id="skapa-hmi-anslutning-till-plc" tabindex="-1">Skapa HMI-anslutning till PLC <a class="header-anchor" href="#skapa-hmi-anslutning-till-plc" aria-label="Permalink to &quot;Skapa HMI-anslutning till PLC&quot;">​</a></h2><h3 id="steg-1-lagg-till-hmi-i-projektet" tabindex="-1">Steg 1: Lägg till HMI i projektet <a class="header-anchor" href="#steg-1-lagg-till-hmi-i-projektet" aria-label="Permalink to &quot;Steg 1: Lägg till HMI i projektet&quot;">​</a></h3><ol><li>Högerklicka på projektet → <strong>Add new device</strong></li><li>Välj <strong>HMI</strong> → <strong>SIMATIC Basic Panel</strong> (eller Comfort)</li><li>Välj panelmodell, ex: <strong>KTP700 Basic PN</strong></li><li><strong>HMI device wizard</strong> startar automatiskt</li></ol><h3 id="steg-2-konfigurera-plc-anslutning" tabindex="-1">Steg 2: Konfigurera PLC-anslutning <a class="header-anchor" href="#steg-2-konfigurera-plc-anslutning" aria-label="Permalink to &quot;Steg 2: Konfigurera PLC-anslutning&quot;">​</a></h3><p>I wizarden:</p><ol><li><strong>PLC connections</strong>: Klicka <strong>Browse</strong> → Välj din PLC</li><li>Anslutningstyp: <strong>HMI connection</strong> (standard)</li><li>Interface: Profinet väljs automatiskt</li><li>Klicka <strong>Finish</strong></li></ol><div class="tip custom-block"><p class="custom-block-title">Manuell anslutning</p><p>Om du hoppade över wizarden:</p><ol><li>HMI → <strong>Connections</strong> → <strong>Add new connection</strong></li><li>Välj <strong>S7-1200</strong> eller <strong>S7-1500</strong></li><li>Konfigurera IP-adress manuellt</li></ol></div><h3 id="steg-3-verifiera-i-network-view" tabindex="-1">Steg 3: Verifiera i Network view <a class="header-anchor" href="#steg-3-verifiera-i-network-view" aria-label="Permalink to &quot;Steg 3: Verifiera i Network view&quot;">​</a></h3><ol><li><strong>Device &amp; Networks</strong> → <strong>Network view</strong></li><li>Kontrollera att en <strong>lila linje</strong> finns mellan HMI och PLC</li><li>Lila = HMI-connection (data exchange)</li></ol><h2 id="anslutningsparametrar" tabindex="-1">Anslutningsparametrar <a class="header-anchor" href="#anslutningsparametrar" aria-label="Permalink to &quot;Anslutningsparametrar&quot;">​</a></h2><h3 id="connection-settings" tabindex="-1">Connection settings <a class="header-anchor" href="#connection-settings" aria-label="Permalink to &quot;Connection settings&quot;">​</a></h3><p>I HMI → <strong>Connections</strong> → Dubbelklicka på anslutningen:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Beskrivning</th><th>Rekommenderat</th></tr></thead><tbody><tr><td><strong>Cycle time</strong></td><td>Uppdateringsintervall</td><td>100-500 ms</td></tr><tr><td><strong>Connection timeout</strong></td><td>Max väntetid</td><td>10 sekunder</td></tr><tr><td><strong>Keep alive</strong></td><td>Håll anslutning aktiv</td><td>✅ Aktiverad</td></tr></tbody></table><h3 id="access-point" tabindex="-1">Access Point <a class="header-anchor" href="#access-point" aria-label="Permalink to &quot;Access Point&quot;">​</a></h3><p><strong>Access Point</strong> definierar vilka taggar PLC:n exponerar för HMI.</p><ol><li>I PLC:n, öppna <strong>PLC tags</strong> eller <strong>DB</strong></li><li>Markera tagg → <strong>Properties</strong> → <strong>HMI accessible</strong> ✅</li><li>Endast markerade taggar kan läsas/skrivas från HMI</li></ol><div class="warning custom-block"><p class="custom-block-title">Säkerhet</p><p>Aktivera <strong>inte</strong> HMI-åtkomst för känsliga taggar som säkerhetskritiska värden eller systemparametrar.</p></div><h2 id="dataoverforing-hmi-→-plc" tabindex="-1">Dataöverföring: HMI → PLC <a class="header-anchor" href="#dataoverforing-hmi-→-plc" aria-label="Permalink to &quot;Dataöverföring: HMI → PLC&quot;">​</a></h2><h3 id="skriva-varden-setpoints" tabindex="-1">Skriva värden (Setpoints) <a class="header-anchor" href="#skriva-varden-setpoints" aria-label="Permalink to &quot;Skriva värden (Setpoints)&quot;">​</a></h3><p>När operatören matar in ett värde på HMI:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[HMI Input Field] ──(Tag-koppling)──&gt; [PLC Tag/DB]</span></span></code></pre></div><p><strong>Exempel i WinCC:</strong></p><ol><li>Lägg till <strong>I/O Field</strong> på skärm</li><li><strong>Properties</strong> → <strong>Process</strong> → <strong>Tag</strong></li><li>Välj PLC-tagg, ex: <code>Motor_Data.Speed_Setpoint</code></li><li><strong>Mode</strong>: Input/Output</li></ol><h3 id="trigga-funktioner-knappar" tabindex="-1">Trigga funktioner (Knappar) <a class="header-anchor" href="#trigga-funktioner-knappar" aria-label="Permalink to &quot;Trigga funktioner (Knappar)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[HMI Button Press] ──(Event)──&gt; [SetBit på PLC-tagg]</span></span></code></pre></div><p><strong>Konfiguration:</strong></p><ol><li>Lägg till <strong>Button</strong> på skärm</li><li><strong>Events</strong> → <strong>Press</strong></li><li>Lägg till funktion: <strong>SetBit</strong> eller <strong>SetBitWhileKeyPressed</strong></li><li>Välj tagg: <code>Control.Start_Button</code></li></ol><h3 id="skicka-kommandoord" tabindex="-1">Skicka kommandoord <a class="header-anchor" href="#skicka-kommandoord" aria-label="Permalink to &quot;Skicka kommandoord&quot;">​</a></h3><p>För mer komplex styrning, använd ett <strong>kommandoord</strong> (Command word):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// PLC-sida (DB)</span></span>
<span class="line"><span>Command_Word : WORD;   // Bits för olika kommandon</span></span>
<span class="line"><span>//  Bit 0 = Start</span></span>
<span class="line"><span>//  Bit 1 = Stop</span></span>
<span class="line"><span>//  Bit 2 = Reset</span></span>
<span class="line"><span>//  Bit 3 = Manual mode</span></span></code></pre></div><p>HMI skriver till Command_Word med <strong>SetBit/ResetBit</strong> funktioner.</p><h2 id="dataoverforing-plc-→-hmi" tabindex="-1">Dataöverföring: PLC → HMI <a class="header-anchor" href="#dataoverforing-plc-→-hmi" aria-label="Permalink to &quot;Dataöverföring: PLC → HMI&quot;">​</a></h2><h3 id="visa-processdata" tabindex="-1">Visa processdata <a class="header-anchor" href="#visa-processdata" aria-label="Permalink to &quot;Visa processdata&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[PLC Tag/DB] ──(Cyklisk läsning)──&gt; [HMI Display Field]</span></span></code></pre></div><p><strong>Exempel:</strong></p><ol><li>Lägg till <strong>I/O Field</strong> med mode <strong>Output</strong></li><li>Koppla till PLC-tagg: <code>Sensors.Temperature_Actual</code></li><li>Formatering: Decimal, enhet °C</li></ol><h3 id="statusindikering" tabindex="-1">Statusindikering <a class="header-anchor" href="#statusindikering" aria-label="Permalink to &quot;Statusindikering&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[PLC Bool-tagg] ──(Trigger)──&gt; [HMI Symbol/Färgändring]</span></span></code></pre></div><p><strong>Konfiguration:</strong></p><ol><li>Lägg till <strong>Circle</strong> eller <strong>Rectangle</strong></li><li><strong>Animations</strong> → <strong>Appearance</strong></li><li>Tagg: <code>Motor.Running</code></li><li><strong>TRUE</strong> = Grön, <strong>FALSE</strong> = Grå</li></ol><h3 id="alarm-och-handelser" tabindex="-1">Alarm och händelser <a class="header-anchor" href="#alarm-och-handelser" aria-label="Permalink to &quot;Alarm och händelser&quot;">​</a></h3><p>PLC skickar larm via <strong>HMI Alarms</strong>:</p><ol><li>HMI → <strong>Alarms</strong> → <strong>Discrete alarms</strong></li><li>Lägg till larm → Koppla till PLC-tagg</li><li>Tagg TRUE = Larm aktivt</li></ol><h2 id="optimera-kommunikationen" tabindex="-1">Optimera kommunikationen <a class="header-anchor" href="#optimera-kommunikationen" aria-label="Permalink to &quot;Optimera kommunikationen&quot;">​</a></h2><h3 id="_1-anvand-acquisition-cycle" tabindex="-1">1. Använd acquisition cycle <a class="header-anchor" href="#_1-anvand-acquisition-cycle" aria-label="Permalink to &quot;1. Använd acquisition cycle&quot;">​</a></h3><p>Sätt olika uppdateringshastigheter för olika taggar:</p><table tabindex="0"><thead><tr><th>Typ av data</th><th>Acquisition cycle</th></tr></thead><tbody><tr><td>Kritiska larm</td><td>100 ms</td></tr><tr><td>Processtatus</td><td>250 ms</td></tr><tr><td>Trender</td><td>1000 ms</td></tr><tr><td>Statiska värden</td><td>On demand</td></tr></tbody></table><p><strong>Konfiguration:</strong></p><ul><li>Tagg → <strong>Properties</strong> → <strong>Acquisition cycle</strong></li></ul><h3 id="_2-gruppera-taggar-i-db" tabindex="-1">2. Gruppera taggar i DB <a class="header-anchor" href="#_2-gruppera-taggar-i-db" aria-label="Permalink to &quot;2. Gruppera taggar i DB&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Bra: En sammanhängande DB</span></span>
<span class="line"><span>&quot;HMI_Interface&quot; [DB10]</span></span>
<span class="line"><span>├── Setpoints (STRUCT)</span></span>
<span class="line"><span>├── Actuals (STRUCT)</span></span>
<span class="line"><span>├── Status (STRUCT)</span></span>
<span class="line"><span>└── Commands (STRUCT)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Dåligt: Spridda taggar överallt</span></span></code></pre></div><p>Sammanhängande minne = effektivare läsning!</p><h3 id="_3-undvik-onodig-polling" tabindex="-1">3. Undvik onödig polling <a class="header-anchor" href="#_3-undvik-onodig-polling" aria-label="Permalink to &quot;3. Undvik onödig polling&quot;">​</a></h3><ul><li>Använd <strong>Events</strong> istället för cyklisk polling för knappar</li><li>Sätt <strong>On change</strong> för värden som sällan ändras</li><li>Minimera antal synliga taggar per skärm</li></ul><h2 id="felsokning" tabindex="-1">Felsökning <a class="header-anchor" href="#felsokning" aria-label="Permalink to &quot;Felsökning&quot;">​</a></h2><h3 id="anslutningsproblem" tabindex="-1">Anslutningsproblem <a class="header-anchor" href="#anslutningsproblem" aria-label="Permalink to &quot;Anslutningsproblem&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symptom</th><th>Möjlig orsak</th><th>Lösning</th></tr></thead><tbody><tr><td>&quot;Connection interrupted&quot;</td><td>Nätverksfel</td><td>Kontrollera kabel, ping PLC</td></tr><tr><td>Taggar visar &quot;###&quot;</td><td>Fel taggkoppling</td><td>Verifiera taggnamn och typ</td></tr><tr><td>Långsam uppdatering</td><td>För kort cycle time</td><td>Öka acquisition cycle</td></tr><tr><td>HMI fryser</td><td>CPU-överbelastning</td><td>Minska antal taggar/skärm</td></tr></tbody></table><h3 id="diagnostikverktyg" tabindex="-1">Diagnostikverktyg <a class="header-anchor" href="#diagnostikverktyg" aria-label="Permalink to &quot;Diagnostikverktyg&quot;">​</a></h3><ol><li><p><strong>HMI Runtime</strong> → <strong>System diagnostics</strong></p><ul><li>Visar anslutningsstatus</li><li>Kommunikationsstatistik</li></ul></li><li><p><strong>TIA Portal Online</strong></p><ul><li>Gå online med HMI</li><li><strong>Diagnostics</strong> → Se aktiva fel</li></ul></li><li><p><strong>Ping-test</strong></p><ul><li>Från PC: <code>ping 192.168.0.10</code> (HMI IP)</li><li>Från HMI: <strong>Control Panel</strong> → <strong>Network</strong> → Test</li></ul></li></ol><h3 id="logga-kommunikation" tabindex="-1">Logga kommunikation <a class="header-anchor" href="#logga-kommunikation" aria-label="Permalink to &quot;Logga kommunikation&quot;">​</a></h3><p>För avancerad felsökning:</p><ol><li>HMI → <strong>Runtime settings</strong> → <strong>Logging</strong></li><li>Aktivera <strong>Communication log</strong></li><li>Analysera loggfil för timeout/fel</li></ol><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/products?search=hmi%20plc%20communication%20tia%20portal" target="_blank" rel="noreferrer">Siemens: HMI-PLC Communication (sökresultat)</a></li><li><a href="https://support.industry.siemens.com/cs/products?search=wincc%20connection%20configuration" target="_blank" rel="noreferrer">Siemens: WinCC Comfort/Advanced konfiguration</a></li></ul><hr><p><strong>Relaterat:</strong></p><ul><li><a href="./hmi-kommunikation.html">HMI-kommunikation (fördjupning)</a></li><li><a href="./../05-taggar/koppling-plc-hmi.html">Koppling PLC↔HMI (taggar)</a></li><li><a href="./../07-hmi-design/skarmbilder.html">Skärmbilder och layout</a></li></ul>`,69)])])}const u=a(r,[["render",s]]);export{h as __pageData,u as default};
